struct io_uring_cqe {          /* 16 bytes */
    __u64 user_data;           /* copied from the SQE */
    __s32 res;                 /* bytes, or -errno */
    __u32 flags;
};

struct io_uring_sqe {          /* 64 bytes, simplified */
    __u8  opcode;              /* IORING_OP_READ, ... */
    __u8  flags;               /* IOSQE_* */
    __s32 fd;
    __u64 off;                 /* file offset */
    __u64 addr;                /* buffer or iovec array */
    __u32 len;                 /* bytes or iovec count */
    __u64 user_data;           /* returned in the CQE */
    /* ... op-specific unions and padding ... */
};

unsigned tail = *sq_tail;              /* app owns the SQ tail */
unsigned idx = tail & *sq_mask;
struct io_uring_sqe *sqe = &sqes[idx];
sqe->opcode = IORING_OP_READ;
sqe->fd = fd;
sqe->addr = (unsigned long) buf;
sqe->len = 4096;
sqe->off = 0;
sqe->user_data = 42;
sq_array[idx] = idx;
io_uring_smp_store_release(sq_tail, tail + 1);
io_uring_enter(ring_fd, 1, 1, IORING_ENTER_GETEVENTS, NULL);
unsigned head = *cq_head;              /* app owns the CQ head */
if (head != io_uring_smp_load_acquire(cq_tail)) {
    struct io_uring_cqe *cqe = &cqes[head & *cq_mask];
    handle(cqe->user_data, cqe->res);
    io_uring_smp_store_release(cq_head, head + 1);
}

struct io_uring ring;
io_uring_queue_init(8, &ring, 0);        /* SQ 8, CQ 16 */
for (int i = 0; i < 3; i++) {
    struct io_uring_sqe *sqe = io_uring_get_sqe(&ring);
    io_uring_prep_read(sqe, fd, bufs[i], 4096, i * 4096);
    io_uring_sqe_set_data64(sqe, i);
}
io_uring_submit_and_wait(&ring, 3);      /* one syscall */
struct io_uring_cqe *cqe;
unsigned head, seen = 0;
io_uring_for_each_cqe(&ring, head, cqe) {
    printf("req %llu res %d\n",
           cqe->user_data, cqe->res);
    seen++;
}
io_uring_cq_advance(&ring, seen);
io_uring_queue_exit(&ring);
